import{_ as l,l as p,o as i,c as o,v as e,p as n,x as r,d as s,i as E,S as _}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"吉芬与劣等","description":"","frontmatter":{"title":"吉芬与劣等","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/giffen-inferior.md","filePath":"econ/giffen-inferior.md","lastUpdated":1789023840000}'),d={name:"econ/giffen-inferior.md"};function A(c,a,B,h,f,m){const t=p("Mermaid");return i(),o("div",null,[a[1]||(a[1]=e('<h1 id="吉芬与劣等" tabindex="-1">吉芬与劣等 <a class="header-anchor" href="#吉芬与劣等" aria-label="Permalink to &quot;吉芬与劣等&quot;">​</a></h1><div class="epigraph"><p>收入效应的符号不由凸性决定。劣等使马歇尔自价格弹性可以翻号；吉芬是收入效应压过替代效应的情形。</p><footer>—— 据 Varian, Microeconomic Analysis；Mas-Colell, Whinston and Green 第 3 章整理</footer></div><p><a href="/econ/slutsky-symmetry">上一课</a>（斯勒茨基对称与负半定）。把 \\(\\partial x_i/\\partial p_j\\) 拆成替代项与收入项，并读出 \\(S\\) 对称、负半定。本课不重推那条恒等式，也不再证明 \\(Sp=0\\)。缺口是：收入效应的符号，以及何时马歇尔需求向上倾斜。上一课声明「正常或劣等不是百科」；本课只把这两个符号钉成比较静态的分支。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>替代项 \\(\\partial h_i/\\partial p_i\\le 0\\) 已经有保护。总效应</p> \\[\\frac{\\partial x_i}{\\partial p_i}=\\frac{\\partial h_i}{\\partial p_i}-\\frac{\\partial x_i}{\\partial w}\\,x_i \\]<p>的第二项可正可负。\\(\\partial x_i/\\partial w\\gt 0\\) 称正常，\\(\\partial x_i/\\partial w\\lt 0\\) 称劣等。劣等时收入项为正（涨价等于变穷，劣等品反而多买），有可能压过非正的替代项，使 \\(\\partial x_i/\\partial p_i\\gt 0\\)。这样的商品叫吉芬。缺口不是再拆一次，而是承认：向下倾斜的需求定律不是定理，只是替代压过收入时的正则情形。</p><p>吉芬必须先劣等，且该商品占预算足够大，收入项才撑得起。正常商品不可能吉芬：两项同号（都非正）。交叉价格上，替代可正可负（净替代 / 净互补），再叠加收入项，马歇尔交叉弹性更没有先验符号。</p><h3 id="吉芬是马歇尔现象" tabindex="-1">吉芬是马歇尔现象 <a class="header-anchor" href="#吉芬是马歇尔现象" aria-label="Permalink to &quot;吉芬是马歇尔现象&quot;">​</a></h3><p>希克斯自价格仍非正。补偿过的需求不向上倾斜。吉芬只活在未补偿的 \\(x(p,w)\\) 上。不要说「偏好向上倾斜」——偏好的凸性管的是 \\(S\\)，不是 \\(D_p x\\)。</p><p><span class="marginnote">教科书里的土豆故事是直觉，不是本栏的数据。经验上吉芬罕见，逻辑上合法。主干保留它，以免把需求定律写成公理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从斯勒茨基方程读符号表。固定 \\(S_{ii}\\le 0\\)、\\(x_i\\gt 0\\)：</p><ul><li>正常：收入项为负，总效应必非正。</li><li>劣等但 \\(|S_{ii}|\\) 更大：马歇尔仍向下。</li><li>劣等且收入项压过替代：吉芬，马歇尔向上。</li></ul><p>两商品时，瓦尔拉斯定律限制更死：一种吉芬则另一种必须正常，且交叉项被加总约束绑住。本课不把两商品图画成唯一世界；\\(n\\) 种商品时，几种同时劣等完全可以。</p>',15)),(i(),n(_,null,{default:r(()=>[E(t,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%9B%BF%E4%BB%A3%E6%95%88%E5%BA%94%E9%9D%9E%E6%AD%A3%22%5D%20--%3E%20SUM%5B%22%E9%A9%AC%E6%AD%87%E5%B0%94%E6%80%BB%E6%95%88%E5%BA%94%22%5D%0A%20%20INC%5B%22%E6%94%B6%E5%85%A5%E6%95%88%E5%BA%94%EF%BC%9A%E2%88%82x%2F%E2%88%82w%20%E7%9A%84%E7%AC%A6%E5%8F%B7%22%5D%20--%3E%20SUM%0A%20%20SUM%20--%3E%20N%5B%22%E6%AD%A3%E5%B8%B8%EF%BC%9A%E8%87%AA%E4%BB%B7%E6%A0%BC%E4%B8%8D%E5%90%91%E4%B8%8A%22%5D%0A%20%20SUM%20--%3E%20G%5B%22%E5%8A%A3%E7%AD%89%E4%B8%94%E5%8E%8B%E8%BF%87%E6%9B%BF%E4%BB%A3%EF%BC%9A%E5%90%89%E8%8A%AC%22%5D%0A%20%20G%20--%3E%20LATER%5B%22%E9%9C%80%E6%B1%82%E5%AE%9A%E5%BE%8B%E4%B8%8D%E6%98%AF%E5%85%AC%E7%90%86%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>位似使所有收入弹性为 \\(1\\)，排除劣等，因而排除吉芬。拟线性把收入效应赶到计价物，非计价物不能吉芬。这两刀上一课序已经有；本课只指出它们把吉芬关在门外。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>涨 \\(p_i\\) 有两件事。相对变贵：沿无差异集离开 \\(i\\)（替代）。真实变穷：沿财富轴移动——穷了少买正常品、多买劣等品。总效应是矢量和。吉芬是「穷了更依赖这件劣等品」，超过了「相对变贵该少买」。</p><p>交叉效应同理。净替代由 \\(S_{ij}\\) 的符号说；毛替代还要加 \\(-x_j\\partial x_i/\\partial w\\)。两种商品可以净替代却毛互补，只要收入项够大。后课税收归宿若只看马歇尔弹性，会把收入效应算进「替代」里；要分离，仍回斯勒茨基。</p><p><span class="marginnote">劣等不是「质量差」。定义只是财富导数为负。公交、低档主食可以劣等；吉芬还要它够大、替代够弱。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>角点上 \\(x_i=0\\)，谈不上吉芬：已经不买。可微公式在内点正则处用。加总需求更不必继承个人的劣等：市场弹性是收入分布与个别弹性的混合物。</p><p>也不要把吉芬写成限价簿里的向上倾斜报价。量化栏的冲击与这里的 \\(\\partial x/\\partial p\\) 不是同一对象。本课仍是一个人的马歇尔比较静态。经验拒绝「常见吉芬」并不拒绝理论：理论只说它可以发生，并且一旦发生，需求定律不能当公理用。</p><p>后课默认：谈到自价格弹性，先问正常还是劣等；只有劣等才打开吉芬分支。\\(S\\) 的符号保护不自动传给 \\(x\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>正常：\\(\\partial x_i/\\partial w\\gt 0\\)，马歇尔自价格非正。</li><li>劣等：财富导数为负；再压过替代才是吉芬。</li><li>吉芬是未补偿需求的现象；希克斯需求仍向下。</li><li>位似、拟线性（非计价物）关上门；一般 \\(u\\) 门开着。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；Mas-Colell, Whinston and Green 第 3 章。</li></ul>',11))])}const S=l(d,[["render",A]]);export{u as __pageData,S as default};
